/* ══════════════════════════════════════
   GlobalStone — Shared Stylesheet
   ══════════════════════════════════════ */

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary:     #003F2D;
  --primary-dk:  #012A2D;
  --accent:      #D4A843;
  --accent-dark: #003F2D;
  --dark:        #0D1F1A;
  --text:        #3A4A44;
  --muted:       #6B7B74;
  --border:      #DCE3DF;
  --bg-light:    #F5F6F5;
  --white:       #ffffff;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  color: var(--text);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { color: inherit; }
ul { list-style: none; }
button { font-family: inherit; }

/* ── Containers ── */
.container       { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.container-wide  { max-width: 1380px; margin: 0 auto; padding: 0 40px; }

/* ── Typography ── */
.section-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: var(--accent-dark);
  display: block;
}
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  color: var(--dark);
  font-weight: 700;
  line-height: 1.25;
}
.section-subtitle {
  font-size: 1.05rem;
  color: var(--text);
  line-height: 1.75;
  max-width: 600px;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: .9rem;
  font-weight: 600;
  letter-spacing: .4px;
  border-radius: 3px;
  text-decoration: none;
  transition: all .2s;
  cursor: pointer;
  border: 2px solid transparent;
}
.btn-primary {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}
.btn-primary:hover { background: #005240; border-color: #005240; }

.btn-accent {
  background: var(--accent);
  color: var(--dark);
  border-color: var(--accent);
}
.btn-accent:hover { background: #c8a035; border-color: #c8a035; }

.btn-outline {
  background: transparent;
  color: var(--primary);
  border-color: var(--primary);
}
.btn-outline:hover { background: var(--primary); color: #fff; }

.btn-outline-light {
  background: transparent;
  color: #fff;
  border-color: rgba(255,255,255,.6);
  padding: 10px 22px;
}
.btn-outline-light:hover { background: rgba(255,255,255,.15); border-color: #fff; }

.btn-ghost {
  background: transparent;
  color: var(--accent-dark);
  border-color: transparent;
  padding: 10px 0;
  font-size: .9rem;
}
.btn-ghost:hover { color: var(--primary); }

.btn-sm { padding: 10px 20px; font-size: .84rem; }

/* ══════════════════════════════════════
   HEADER
   ══════════════════════════════════════ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--primary-dk);
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.header-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 48px;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-mark {
  width: 36px; height: 36px;
  background: var(--accent);
  color: var(--dark);
  font-weight: 800;
  font-size: .9rem;
  letter-spacing: .5px;
  border-radius: 4px;
  display: flex; align-items: center; justify-content: center;
}
.logo-text {
  font-size: 1.1rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: .3px;
}
.logo-light .logo-text { color: rgba(255,255,255,.85); }

/* Desktop Nav */
.main-nav { flex: 1; }
.nav-list {
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-link, .nav-btn {
  font-size: .88rem;
  font-weight: 500;
  color: rgba(255,255,255,.8);
  text-decoration: none;
  padding: 8px 14px;
  border-radius: 3px;
  background: none;
  border: none;
  cursor: pointer;
  transition: color .15s, background .15s;
  white-space: nowrap;
}
.nav-link:hover, .nav-btn:hover,
.nav-item.active .nav-link,
.nav-btn[aria-expanded="true"] {
  color: #fff;
  background: rgba(255,255,255,.08);
}

/* Mega Menu */
.has-mega { position: static; }
.mega-menu {
  display: none;
  position: absolute;
  left: 0; right: 0;
  top: 72px;
  background: #fff;
  border-top: 3px solid var(--accent);
  box-shadow: 0 20px 60px rgba(0,0,0,.15);
  z-index: 999;
}
.mega-menu.open { display: block; }
.mega-inner {
  display: grid;
  grid-template-columns: 1fr 1fr 1.2fr;
  gap: 0;
  padding: 40px 40px 48px;
}
.mega-col { padding: 0 40px 0 0; }
.mega-col:last-child { border-left: 1px solid var(--border); padding-left: 40px; padding-right: 0; }
.mega-heading {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 16px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
}
.mega-col ul { display: flex; flex-direction: column; gap: 2px; }
.mega-col ul li a {
  font-size: .9rem;
  font-weight: 500;
  color: var(--dark);
  text-decoration: none;
  padding: 8px 12px;
  border-radius: 3px;
  display: block;
  transition: background .15s, color .15s;
}
.mega-col ul li a:hover { background: var(--bg-light); color: var(--primary); }
.mega-featured {}
.mega-feature-card {
  background: var(--bg-light);
  border-radius: 6px;
  padding: 24px;
  border-left: 4px solid var(--accent);
}
.mega-feature-tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--accent-dark);
  margin-bottom: 8px;
}
.mega-feature-card h4 { font-size: .95rem; font-weight: 700; color: var(--dark); line-height: 1.4; margin-bottom: 16px; }
.mega-feature-link { font-size: .88rem; font-weight: 700; color: var(--accent-dark); text-decoration: none; }
.mega-feature-link:hover { text-decoration: underline; }

/* Mobile Toggle */
.mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  margin-left: auto;
}
.mobile-toggle span {
  display: block;
  width: 24px; height: 2px;
  background: rgba(255,255,255,.85);
  transition: all .25s;
  border-radius: 2px;
}
.mobile-toggle.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.mobile-toggle.open span:nth-child(2) { opacity: 0; }
.mobile-toggle.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* Mobile Nav */
.mobile-nav {
  display: none;
  background: var(--primary-dk);
  border-top: 1px solid rgba(255,255,255,.08);
  overflow-y: auto;
  max-height: calc(100vh - 72px);
}
.mobile-nav.open { display: block; }
.mobile-nav-list { padding: 16px 0 24px; }
.mobile-nav-item { border-bottom: 1px solid rgba(255,255,255,.06); }
.mobile-nav-btn {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  background: none;
  border: none;
  color: rgba(255,255,255,.85);
  font-size: .95rem;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
}
.mobile-nav-btn svg { transition: transform .2s; flex-shrink: 0; stroke: currentColor; }
.mobile-nav-btn[aria-expanded="true"] svg { transform: rotate(180deg); }
.mobile-nav-link {
  display: block;
  padding: 16px 24px;
  color: rgba(255,255,255,.8);
  font-size: .95rem;
  text-decoration: none;
  font-weight: 500;
}
.mobile-accordion {
  display: none;
  padding: 8px 0 16px;
  background: rgba(0,0,0,.15);
}
.mobile-accordion.open { display: block; }
.mobile-acc-heading {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(255,255,255,.4);
  padding: 12px 24px 6px;
}
.mobile-accordion a {
  display: block;
  padding: 10px 24px 10px 32px;
  color: rgba(255,255,255,.75);
  font-size: .9rem;
  text-decoration: none;
}
.mobile-accordion a:hover { color: #fff; background: rgba(255,255,255,.05); }

/* ══════════════════════════════════════
   PAGE HERO (service pages)
   ══════════════════════════════════════ */
.page-hero {
  position: relative;
  padding: 100px 0 80px;
  background: linear-gradient(135deg, #012A2D 0%, #003F2D 100%);
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?w=1400&q=70') center/cover no-repeat;
  opacity: .12;
}
.page-hero-content { position: relative; z-index: 1; }
.page-hero-label { font-size: 11px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: var(--accent); margin-bottom: 16px; display: block; }
.page-hero h1 { font-family: 'Playfair Display', serif; font-size: clamp(2rem, 4vw, 3rem); color: #fff; line-height: 1.2; margin-bottom: 20px; max-width: 680px; }
.page-hero p { font-size: 1.1rem; color: rgba(255,255,255,.75); max-width: 560px; line-height: 1.75; margin-bottom: 36px; }

/* ══════════════════════════════════════
   INTRO STATEMENT
   ══════════════════════════════════════ */
.intro-statement { padding: 80px 0; background: #fff; }
.intro-inner { max-width: 820px; }
.intro-inner h2 { font-family: 'Playfair Display', serif; font-size: clamp(1.5rem, 3vw, 2.2rem); color: var(--dark); margin-bottom: 20px; line-height: 1.3; }
.intro-inner p { font-size: 1.05rem; color: var(--text); line-height: 1.8; margin-bottom: 16px; }

/* ══════════════════════════════════════
   CAPABILITIES GRID
   ══════════════════════════════════════ */
.capabilities { padding: 80px 0; background: var(--bg-light); }
.capabilities h2 { font-family: 'Playfair Display', serif; font-size: 2rem; color: var(--dark); margin-bottom: 48px; }
.cap-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.cap-card {
  background: #fff;
  border-radius: 4px;
  padding: 36px 30px 40px;
  border: 1px solid var(--border);
  transition: border-color .2s, box-shadow .2s, transform .2s;
  position: relative;
}
.cap-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .2s;
  border-radius: 4px 4px 0 0;
}
.cap-card:hover { border-color: transparent; box-shadow: 0 8px 32px rgba(0,63,45,.1); transform: translateY(-2px); }
.cap-card:hover::before { transform: scaleX(1); }
.cap-num { font-size: .78rem; font-weight: 700; letter-spacing: 2px; color: var(--accent-dark); opacity: .5; margin-bottom: 16px; }
.cap-card h3 { font-size: 1.05rem; font-weight: 700; color: var(--dark); margin-bottom: 12px; line-height: 1.4; }
.cap-card p { font-size: .9rem; color: var(--text); line-height: 1.75; margin-bottom: 20px; }
.cap-card a { font-size: .85rem; font-weight: 600; color: var(--accent-dark); text-decoration: none; border-bottom: 1px solid transparent; transition: border-color .2s; }
.cap-card a:hover { border-color: var(--accent-dark); }

@media (max-width: 1024px) { .cap-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 640px) { .cap-grid { grid-template-columns: 1fr; } }

/* ══════════════════════════════════════
   RELATED INSIGHTS
   ══════════════════════════════════════ */
.related-insights { padding: 80px 0; background: #fff; }
.related-insights h2 { font-family: 'Playfair Display', serif; font-size: 2rem; color: var(--dark); margin-bottom: 40px; }
.ri-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.ri-card { border: 1px solid var(--border); border-radius: 4px; overflow: hidden; transition: box-shadow .2s; }
.ri-card:hover { box-shadow: 0 4px 20px rgba(0,63,45,.08); }
.ri-card-img { height: 160px; background: linear-gradient(135deg, var(--primary-dk), var(--primary)); overflow: hidden; }
.ri-card-img img { width: 100%; height: 100%; object-fit: cover; opacity: .75; }
.ri-card-body { padding: 22px; }
.ri-tag { font-size: 10px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--accent-dark); margin-bottom: 8px; display: block; }
.ri-card-body h3 { font-size: .9rem; font-weight: 600; color: var(--dark); line-height: 1.5; margin-bottom: 12px; }
.ri-card-body a { font-size: .84rem; color: var(--accent-dark); font-weight: 600; text-decoration: none; }

@media (max-width: 768px) { .ri-grid { grid-template-columns: 1fr; } }

/* ══════════════════════════════════════
   FOOTER
   ══════════════════════════════════════ */
.site-footer { background: var(--primary-dk); padding: 64px 0 0; }
.footer-inner {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 80px;
  padding-bottom: 56px;
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.footer-brand .logo { margin-bottom: 16px; }
.footer-tagline { font-size: .88rem; color: rgba(255,255,255,.5); line-height: 1.6; max-width: 240px; }
.footer-links { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; }
.footer-col h4 { font-size: .85rem; font-weight: 700; color: rgba(255,255,255,.9); margin-bottom: 16px; letter-spacing: .3px; }
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col ul li a { font-size: .84rem; color: rgba(255,255,255,.5); text-decoration: none; transition: color .15s; }
.footer-col ul li a:hover { color: rgba(255,255,255,.9); }
.footer-bottom { padding: 20px 0; }
.footer-bottom-inner { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; }
.footer-copy { font-size: .8rem; color: rgba(255,255,255,.35); }
.footer-legal { display: flex; gap: 24px; flex-wrap: wrap; }
.footer-legal a { font-size: .78rem; color: rgba(255,255,255,.35); text-decoration: none; transition: color .15s; }
.footer-legal a:hover { color: rgba(255,255,255,.65); }

@media (max-width: 1024px) {
  .footer-inner { grid-template-columns: 1fr; gap: 40px; }
  .footer-links { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .footer-links { grid-template-columns: 1fr; }
  .container-wide { padding: 0 20px; }
  .footer-bottom-inner { flex-direction: column; align-items: flex-start; }
}

/* ══════════════════════════════════════
   NAV RESPONSIVE
   ══════════════════════════════════════ */
@media (max-width: 1024px) {
  .main-nav { display: none; }
  .mobile-toggle { display: flex; }
  .container-wide { padding: 0 20px; }
  .header-inner { gap: 0; }
}

